with RecursiveTagSum as (
    select
        t.Id,
        t.TagName,
        t.Count,
        coalesce((select sum(p.Views) 
                  from Posts p 
                  where p.PostTypeId = 1 and p.Tags like concat('%<', t.TagName ,'>%')), 0) as TotalViews,
        1 as Level
    from Tags t
    where t.IsRequired = 1
    union all
    select
        t.Id,
        t.TagName,
        t.Count,
        coalesce(rt.TotalViews, 0) + t.Count * 10 as TotalViews,
        r.Level + 1
    from Tags t
    join RecursiveTagSum r on t.IsModeratorOnly = 0 and r.Level < 2 -- quickly limit recursion for performance hit
